import{_ as i,o as a,c as o,ag as n}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Specification, Provider, and publication evidence policy","description":"","frontmatter":{},"headers":[],"relativePath":"spec/publication-freeze.md","filePath":"spec/publication-freeze.md"}'),t={name:"spec/publication-freeze.md"};function r(c,e,s,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="specification-provider-and-publication-evidence-policy" tabindex="-1">Specification, Provider, and publication evidence policy <a class="header-anchor" href="#specification-provider-and-publication-evidence-policy" aria-label="Permalink to &quot;Specification, Provider, and publication evidence policy&quot;">​</a></h1><p>Takoform has independent release and publication axes. Evidence from one axis MUST NOT be treated as authority for another.</p><h2 id="specification-1-0" tabindex="-1">Specification 1.0 <a class="header-anchor" href="#specification-1-0" aria-label="Permalink to &quot;Specification 1.0&quot;">​</a></h2><p>The normative Specification 1.0 track defines the literal stable Host API lane <code>forms.takoform.com/v1</code>. It closes only when all three of these Takoform-owned facts are committed and exact:</p><ol><li>one complete Specification source snapshot;</li><li>the generator-owned multi-family candidate and corpus closure; and</li><li>the manifest-owned reference conformance execution.</li></ol><p>The canonical machine policy is <a href="publication-evidence.json"><code>publication-evidence.json</code></a>, and the numbered release candidate/ledger is <a href="../release/specification-releases.json"><code>../release/specification-releases.json</code></a>. Decisions <a href="./decisions/0052-the-specification-is-released-on-its-own-line.html">0052</a> and <a href="./decisions/0053-specification-and-provider-release-evidence.html">0053</a> define the boundary.</p><p>The current generator index contains eight versionless families and 31 exact Experimental <code>0.x</code> FormRefs. Edge contains 16 and has no current <code>ObjectBucket</code>, <code>edge.objects</code>, or <code>module-worker.object-bucket</code>. The stable standard-service contract is <code>standards.takoform.com/v1</code>; protocol identifiers are opaque reverse-DNS strings, not a Takoform-owned enum.</p><p>Releasing Specification/Host API v1 does not:</p><ul><li>relabel any current Form as <code>1.0.0</code> or Stable;</li><li>publish a Form Package, Interface, or Binding;</li><li>release Provider 3;</li><li>prove any Host, backend, runtime, or product supports the contract; or</li><li>authorize a commit, tag, publication, deployment, signing action, or production change.</li></ul><p>A future Stable Form begins at <code>1.0.0</code> only through an explicit per-Form decision. Form maturity remains independent from the Host API and numbered Specification.</p><h2 id="official-provider" tabindex="-1">Official Provider <a class="header-anchor" href="#official-provider" aria-label="Permalink to &quot;Official Provider&quot;">​</a></h2><p>The Terraform Provider is an independent implementation stream. Provider 2.1.1 and its exact Host v1beta1/versioned Edge 15-Form identities remain immutable Registry history.</p><p>Provider 3 is an official but non-normative sample. Its evidence track may bind the exact current Form projection, Provider identity ledger, retained codecs, state continuity, and migration behavior. It can remain open while Specification 1.0 closes, and a green Provider milestone cannot close the Specification track.</p><h2 id="adoption-evidence" tabindex="-1">Adoption evidence <a class="header-anchor" href="#adoption-evidence" aria-label="Permalink to &quot;Adoption evidence&quot;">​</a></h2><p>Independent Hosts, Takoserver, Takosumi, other backends, runtime ABI reports, production consumers, compatibility windows, package publishers, signers, and operators may record adoption evidence in their owning repositories. Those facts are useful for support, implementation confidence, and product readiness. They are not Takoform release authorities and can neither add a Specification prerequisite nor substitute for one.</p><p>Decisions 0044 and 0046 are retained as adoption-program history. Decision 0053 supersedes them as Specification and Provider release gates.</p><h2 id="retained-publication-history" tabindex="-1">Retained publication history <a class="header-anchor" href="#retained-publication-history" aria-label="Permalink to &quot;Retained publication history&quot;">​</a></h2><p><a href="publication-blockers.json"><code>publication-blockers.json</code></a> records an earlier v1beta1 Form Package/public-service attempt. Its bytes and open statuses remain immutable historical truth. The new Specification assertion does not rewrite or require closure of those rows.</p><p>Likewise:</p><ul><li>published schema identities remain append-only in <a href="../release/public-schema-identities.json"><code>../release/public-schema-identities.json</code></a>;</li><li>occupied document lanes remain recorded in <a href="../release/published-document-lanes.json"><code>../release/published-document-lanes.json</code></a>;</li><li>Provider release and FormRef identities remain append-only in the release ledgers; and</li><li>retired or retained bytes are never republished under a different meaning.</li></ul><p>The historical <code>assert:publishable</code> command remains the assertion for that old Form Package/public-service obligation set. It is not a Specification 1.0 or Provider 3 gate.</p><h2 id="fail-closed-checks" tabindex="-1">Fail-closed checks <a class="header-anchor" href="#fail-closed-checks" aria-label="Permalink to &quot;Fail-closed checks&quot;">​</a></h2><ul><li><code>bun run check:publication-evidence</code> validates both independent track shapes and reports their open/ready state.</li><li><code>bun run check:specification-releases</code> validates the numbered candidate and protects committed release entries append-only.</li><li><code>bun run check:specification-v1-release</code> asserts only the three normative Specification prerequisites.</li><li><code>bun run check:provider-v3-release</code> asserts only the non-normative Provider milestone.</li><li><code>bun run check:takoform-milestones</code> asserts both as an optional project checkpoint.</li></ul><p>The Specification evidence record intentionally keeps its family-index and suite pointers and all derived evidence objects <code>null</code> until one clean, reachable commit contains the frozen bytes. A dirty, staged, untracked, partial, unreachable, caller-renamed, or digest-mismatched closure fails. A generic <code>pass</code>, hand-written count, external receipt, or signature policy cannot make it ready.</p><p>There is no <code>stable-mint</code> alias. The readiness assertion does not silently promote Forms or packages.</p>',25)])])}const m=i(t,[["render",r]]);export{u as __pageData,m as default};
